-- REM-A4-PROGRAMS-1 (2026-10-26, charter pillar autonomy; session rem-a4 fork F5): the closing probes of five program/lever issues measure their own definition of done.
-- Measured 2026-10-26 17:54Z to 20:10Z in qnfo-audit before this file:
--   100299 ISSUE-AGE-24H-1: the contract probe read metric_registry.last_value once (an instant reading, not the owner's "0 for seven consecutive daily reads"); the action text still said VACUOUS-PROBE-V3-1.
--     metric_history holds one row per UTC day: 70, 114, 173, 202, 203, 277, 122 (issues_over_24h_no_doer). 156 open issues are older than 24 h: 98 have no doer, 43 count as having one only because their text carries a
--     code-task line (20 of those have no live code task: every task failed or none was built), 15 have a live work claim, 0 a live code task.
--   100294 ISSUE-THROUGHPUT-FAMILIES-1: the probe counted families but not the second clause of the definition of done (issue_drain_ratio_24h at or above 1.5; live 1.225). Seven families have net inflow above 0 with three or more open:
--     ROOT-CAUSE-1 10/0, BREACH-DOCTOR-1 7/0, METRIC-FIX-RELAPSED-1 8/2, METRIC-REGRESSION-1 13/8, METRIC-UNMEASURED-1 7/2, LOOP-BREAKER-1 8/6, FLEET-JOURNEY-FAILED-1 5/4 (opened/closed in 24 h). The three families the issue was filed for
--     (RESEARCH-TERMINAL, PAPER-LEARN-1, VERIFICATION-DEFERRED-7D-1) are no longer in that list.
--   100279 TP-1.23 CODE-LOOP-CONTROL-PLANE-1: lever row tp=1 n=23 is verified (landed 2026-10-20T04:00Z); 36 code tasks on the loop-canaried workers are merged with merge_state verified (14 on fleet-control/ops/deploy-guard/orchestrator, first
--     2026-10-19T14:35Z); one CONTROL-PLANE-REVERTED-1 issue since (1000171, 2026-10-25, a canary race on a session push of qnfo-gateway, sha 7a9d293, no code task carries it). Its two contracts were a loop-owned monitoring stub (not probed)
--     and a probe judged partial that counted every revert, loop or not.
--   100318 TP-1.17 and 100366 TP-2.3: both held a loop-owned monitoring stub (never probed) next to a probe-review-refused backfill contract. 100318: qnfo-ai and qnfo-gateway are already in PLAN_LOOP_CANARIED (12 and 7 loop merges verified in
--     7 days); deployment_history holds 224 plain deploy rows for them and no staged row. 100366: metric_registry holds no per-worker request count.
-- WHAT THIS FILE DOES (data only, no worker change, no cap or threshold touched): each issue gets ONE active contract on its own class issue-<id> whose probe measures the definition of done and reads a reason ("pending: ...") until it holds;
-- the refused or superseded backfill twins of 100279, 100318 and 100366 are superseded by it; the backup of the pre-change rows is bak_20261026_rem_a4_programs (the Rollback line restores from it); the issues get a dated note; one decision_log row.
-- 100293 keeps its probe (it already measures queue minutes, merged share over two windows and closed against opened); only a note records the measured decomposition.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: UPDATE remediation_contracts SET verify_probe = (SELECT b.verify_probe FROM bak_20261026_rem_a4_programs b WHERE b.class = remediation_contracts.class), action = (SELECT b.action FROM bak_20261026_rem_a4_programs b WHERE b.class = remediation_contracts.class), status = (SELECT b.status FROM bak_20261026_rem_a4_programs b WHERE b.class = remediation_contracts.class), module = (SELECT b.module FROM bak_20261026_rem_a4_programs b WHERE b.class = remediation_contracts.class), max_attempts = (SELECT b.max_attempts FROM bak_20261026_rem_a4_programs b WHERE b.class = remediation_contracts.class), last_verdict = (SELECT b.last_verdict FROM bak_20261026_rem_a4_programs b WHERE b.class = remediation_contracts.class) WHERE class IN (SELECT class FROM bak_20261026_rem_a4_programs)

CREATE TABLE IF NOT EXISTS bak_20261026_rem_a4_programs AS
  SELECT * FROM remediation_contracts
   WHERE class IN ('issue-100299', 'issue-100294', 'issue-100279', 'issue-100279-BACKFILL-1', 'issue-100318', 'issue-100318-BACKFILL-1', 'issue-100366', 'issue-100366-BACKFILL-1');

-- 100299: seven consecutive daily reads at 0
UPDATE remediation_contracts SET
  status = 'active', module = 'rem-a4-programs', max_attempts = 1000, attempts = 0, last_verdict = NULL, next_due_at = datetime('now'),
  action = 'MEASURES the defect (ISSUE-AGE-24H-1, owner directive 2026-10-20: every open issue is cleared server-side within 24 hours; done when issues_over_24h_no_doer is 0 for seven consecutive daily reads). Reads 7 only when metric_history holds a daily read of 0 for each of the last 7 UTC days; otherwise it observes how many of the 7 days read 0 and the latest read. Live 2026-10-26: daily reads 70, 114, 173, 202, 203, 277, 122, none zero. The work is a doer for every open issue older than 24 hours: the breach doctor (BREACH-DOCTOR-1, Phase B counts a live doctor lease as a doer), the code loop and sessions. The metric formula and its target are not changed.',
  verify_probe = 'SELECT ''7'' AS expected, CASE WHEN (SELECT COUNT(*) FROM metric_history WHERE metric = ''issues_over_24h_no_doer'' AND day >= date(''now'', ''-6 days'') AND value = 0) >= 7 THEN ''7'' ELSE (SELECT COUNT(*) FROM metric_history WHERE metric = ''issues_over_24h_no_doer'' AND day >= date(''now'', ''-6 days'') AND value = 0) || '' of the last 7 daily reads are 0 (latest read '' || COALESCE((SELECT CAST(value AS INTEGER) FROM metric_history WHERE metric = ''issues_over_24h_no_doer'' ORDER BY day DESC LIMIT 1), ''none'') || '')'' END AS observed'
WHERE class = 'issue-100299' AND instr(verify_probe, 'metric_history') = 0;

-- 100294: no family with net inflow, and the drain ratio of the definition of done
UPDATE remediation_contracts SET
  status = 'active', module = 'rem-a4-programs', max_attempts = 1000, attempts = 0, last_verdict = NULL, next_due_at = datetime('now'),
  action = 'MEASURES the defect (ISSUE-THROUGHPUT-FAMILIES-1, owner directive ISSUE-THROUGHPUT-1). Reads ok only when no family in v_issue_family_throughput has net_inflow_24h above 0 with three or more issues open AND the metric issue_drain_ratio_24h is at least 1.5, the two clauses of the definition of done; otherwise it observes the first failing clause with its numbers and the largest families. Live 2026-10-26 20:10Z: 7 families (ROOT-CAUSE-1, BREACH-DOCTOR-1, METRIC-FIX-RELAPSED-1, METRIC-REGRESSION-1, METRIC-UNMEASURED-1, LOOP-BREAKER-1, FLEET-JOURNEY-FAILED-1), ratio 1.225. The three families named in the title are no longer leaking. The work is each family''s owning loop (see the dated note on the issue); nothing is closed to lower inflow.',
  verify_probe = 'SELECT ''ok'' AS expected, CASE WHEN (SELECT COUNT(*) FROM v_issue_family_throughput WHERE net_inflow_24h > 0 AND open_now >= 3) > 0 THEN ''pending: '' || (SELECT COUNT(*) FROM v_issue_family_throughput WHERE net_inflow_24h > 0 AND open_now >= 3) || '' families have net inflow above 0 with three or more open, largest '' || COALESCE((SELECT group_concat(family || '' +'' || net_inflow_24h, '', '') FROM (SELECT family, net_inflow_24h FROM v_issue_family_throughput WHERE net_inflow_24h > 0 AND open_now >= 3 ORDER BY net_inflow_24h DESC LIMIT 3)), ''none'') WHEN COALESCE((SELECT CAST(last_value AS REAL) FROM metric_registry WHERE metric = ''issue_drain_ratio_24h''), 0) < 1.5 THEN ''pending: issue_drain_ratio_24h '' || COALESCE((SELECT last_value FROM metric_registry WHERE metric = ''issue_drain_ratio_24h''), ''unmeasured'') || '' is below 1.5'' ELSE ''ok'' END AS observed'
WHERE class = 'issue-100294' AND instr(verify_probe, 'issue_drain_ratio_24h') = 0;

-- 100279: the loop's control-plane merges are verified and none was reverted for 7 days after the lever landed
UPDATE remediation_contracts SET
  status = 'active', module = 'rem-a4-programs', max_attempts = 1000, attempts = 0, last_verdict = NULL, next_due_at = datetime('now'),
  action = 'MEASURES the defect (TP-1.23 CODE-LOOP-CONTROL-PLANE-1: a code task on a control-plane worker is planned, merged by the runner and verified by the canary; no CONTROL-PLANE-REVERTED-1 over the following 7 days). Reads ok only when the lever row tp=1 n=23 is landed or verified and landed at least 7 days ago, at least one code task on qnfo-fleet-control, qnfo-ops, qnfo-deploy-guard or qnfo-code-orchestrator is merged with merge_state verified, no loop-canaried code task merged in the last 7 days ended reverted or revert-failed, and no CONTROL-PLANE-REVERTED-1 issue of the last 7 days names the push of a code-task merge. Live 2026-10-26: lever verified (landed 2026-10-20T04:00Z), 14 verified merges on the four workers, one revert issue (1000171, 2026-10-25, a canary race on a session push of qnfo-gateway, sha 7a9d293, carried by no code task), so the first read after 2026-10-27T04:00Z is the earliest that can pass. Replaces the loop-owned monitoring stub and the backfill twin.',
  verify_probe = 'SELECT ''ok'' AS expected, CASE WHEN (SELECT COUNT(*) FROM transformation_levers WHERE tp = 1 AND n = 23 AND status IN (''landed'', ''verified'')) < 1 THEN ''pending: lever TP-1.23 is not landed'' WHEN (SELECT COUNT(*) FROM code_tasks WHERE status = ''merged'' AND merge_state = ''verified'' AND merged_at >= ''2026-10-19'' AND path IN (''qnfo-fleet-control/worker.js'', ''qnfo-ops/worker.js'', ''qnfo-deploy-guard/worker.js'', ''qnfo-code-orchestrator/worker.js'')) < 1 THEN ''pending: no control-plane code task merged by the runner and verified by the canary'' WHEN COALESCE((SELECT landed_at FROM transformation_levers WHERE tp = 1 AND n = 23), ''9999'') > strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-7 days'') THEN ''pending: the 7-day follow-up after the lever landed (''  || COALESCE((SELECT landed_at FROM transformation_levers WHERE tp = 1 AND n = 23), ''never'') || '') has not elapsed'' WHEN (SELECT COUNT(*) FROM code_tasks WHERE merge_state IN (''reverted'', ''revert-failed'') AND merged_at >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-7 days'') AND path IN (''qnfo-fleet-control/worker.js'', ''qnfo-ops/worker.js'', ''qnfo-deploy-guard/worker.js'', ''qnfo-code-orchestrator/worker.js'', ''qnfo-ai/worker.js'', ''qnfo-gateway/worker.js'')) > 0 THEN ''fail: a code-loop merge on a control-plane worker ended reverted in the last 7 days'' WHEN (SELECT COUNT(*) FROM agent_issues a WHERE a.title LIKE ''CONTROL-PLANE-REVERTED-1:%'' AND a.created_at >= (CAST(strftime(''%s'', ''now'') AS INTEGER) - 604800) * 1000 AND EXISTS (SELECT 1 FROM code_tasks c WHERE c.merged_sha IS NOT NULL AND length(c.merged_sha) >= 7 AND instr(a.title, ''push '' || substr(c.merged_sha, 1, 7) || '' '') > 0)) > 0 THEN ''fail: a CONTROL-PLANE-REVERTED-1 issue of the last 7 days names the push of a code-task merge'' ELSE ''ok'' END AS observed'
WHERE class = 'issue-100279' AND instr(verify_probe, 'transformation_levers') = 0;

-- 100318: a recorded staged promote and rollback for each of the two workers, and the lever landed
UPDATE remediation_contracts SET
  status = 'active', module = 'rem-a4-programs', max_attempts = 1000, attempts = 0, last_verdict = NULL, next_due_at = datetime('now'),
  action = 'MEASURES the defect (TP-1.17 STAGED-ROLLOUT-AI-GATEWAY-1: one live staged deploy of each worker promoted and one rolled back by the path itself; both workers off EVOLVE_DENY, PLAN_DENY_WORKERS and TP_CONTROL_PLANE; a code-loop PR on qnfo-gateway merged by the runner). Reads ok only when deployment_history holds a success row with action staged-promote and one with action staged-rollback for each of qnfo-ai and qnfo-gateway (four rows; the path must write them), the lever row tp=1 n=17 is landed or verified (the lists are the lever''s last step), and a code task on qnfo-gateway is merged with merge_state verified. Live 2026-10-26: 0 of 4 staged rows (224 plain deploy rows), lever status session, 7 verified loop merges on qnfo-gateway and 12 on qnfo-ai in 7 days, qnfo-ai and qnfo-gateway already in PLAN_LOOP_CANARIED so PLAN_DENY_WORKERS no longer holds them. Open: a path that uploads a version, routes a fraction, probes and promotes or rolls back without the changed worker (scripts/cf_ops_actions.py only reads worker-history), then the two list removals in one change. Replaces the loop-owned monitoring stub and the refused backfill twin.',
  verify_probe = 'SELECT ''ok'' AS expected, CASE WHEN (SELECT COUNT(*) FROM (SELECT DISTINCT resource_name, action FROM deployment_history WHERE resource_type = ''worker'' AND resource_name IN (''qnfo-ai'', ''qnfo-gateway'') AND action IN (''staged-promote'', ''staged-rollback'') AND status = ''success'')) < 4 THEN ''pending: '' || (SELECT COUNT(*) FROM (SELECT DISTINCT resource_name, action FROM deployment_history WHERE resource_type = ''worker'' AND resource_name IN (''qnfo-ai'', ''qnfo-gateway'') AND action IN (''staged-promote'', ''staged-rollback'') AND status = ''success'')) || '' of 4 staged deploy rows (a staged-promote and a staged-rollback for each of qnfo-ai and qnfo-gateway) exist in deployment_history'' WHEN (SELECT COUNT(*) FROM transformation_levers WHERE tp = 1 AND n = 17 AND status IN (''landed'', ''verified'')) < 1 THEN ''pending: the staged rows exist but lever TP-1.17 is not landed (both workers must leave EVOLVE_DENY and TP_CONTROL_PLANE)'' WHEN (SELECT COUNT(*) FROM code_tasks WHERE status = ''merged'' AND merge_state = ''verified'' AND path = ''qnfo-gateway/worker.js'') < 1 THEN ''pending: no code task on qnfo-gateway merged by the runner'' ELSE ''ok'' END AS observed'
WHERE class = 'issue-100318' AND instr(verify_probe, 'staged-promote') = 0;

-- 100366: the metric the definition of done needs exists, is under 3000 a day, and the lever landed
UPDATE remediation_contracts SET
  status = 'active', module = 'rem-a4-programs', max_attempts = 1000, attempts = 0, last_verdict = NULL, next_due_at = datetime('now'),
  action = 'MEASURES the defect (TP-2.3 ONE-PROBE-PASS-1: requests on workers with no public route under 3,000 a day). The definition of done had no metric behind it, so no probe could grade it (metric_registry holds no per-worker request count). Reads ok only when metric_registry holds worker_requests_nonpublic_per_day (the daily sum of workersInvocationsAdaptive requests over the live workers that have no public route, produced on a runner from the Cloudflare analytics GraphQL API, which also needs a metric trigger or a named exemption in the same change) with a value under 3000 and the lever row tp=2 n=3 is landed or verified. Live 2026-10-26: the metric is not registered. Open: the daily producer, then the one-pass probe change in qnfo-fleet-control (worker_live_audit read by the dashboard, lifecycle and deploy-guard). Replaces the loop-owned monitoring stub and the refused backfill twin.',
  verify_probe = 'SELECT ''ok'' AS expected, CASE WHEN (SELECT COUNT(*) FROM metric_registry WHERE metric = ''worker_requests_nonpublic_per_day'') < 1 THEN ''pending: metric worker_requests_nonpublic_per_day is not registered, so requests on workers with no public route cannot be graded'' WHEN COALESCE((SELECT CAST(last_value AS REAL) FROM metric_registry WHERE metric = ''worker_requests_nonpublic_per_day''), 1e9) >= 3000 THEN ''pending: worker_requests_nonpublic_per_day '' || COALESCE((SELECT last_value FROM metric_registry WHERE metric = ''worker_requests_nonpublic_per_day''), ''has no value'') || '' is not under 3000'' WHEN (SELECT COUNT(*) FROM transformation_levers WHERE tp = 2 AND n = 3 AND status IN (''landed'', ''verified'')) < 1 THEN ''pending: the metric is under 3000 but lever TP-2.3 is not landed'' ELSE ''ok'' END AS observed'
WHERE class = 'issue-100366' AND instr(verify_probe, 'worker_requests_nonpublic_per_day') = 0;

-- the backfill twins are replaced by the contract on the issue's own class
UPDATE remediation_contracts SET status = 'superseded', last_verdict = 'superseded:REM-A4-PROGRAMS-1 (replaced by the contract on class issue-100279, which measures the definition of done)', last_attempt_at = datetime('now')
 WHERE class = 'issue-100279-BACKFILL-1' AND status <> 'superseded';
UPDATE remediation_contracts SET status = 'superseded', last_verdict = 'superseded:REM-A4-PROGRAMS-1 (replaced by the contract on class issue-100318, which measures the definition of done)', last_attempt_at = datetime('now')
 WHERE class = 'issue-100318-BACKFILL-1' AND status <> 'superseded';
UPDATE remediation_contracts SET status = 'superseded', last_verdict = 'superseded:REM-A4-PROGRAMS-1 (replaced by the contract on class issue-100366, which measures the definition of done)', last_attempt_at = datetime('now')
 WHERE class = 'issue-100366-BACKFILL-1' AND status <> 'superseded';

-- dated notes on the issues (idempotent: one note each)
UPDATE agent_issues SET updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000, description = COALESCE(description, '') || char(10) ||
  'REM-A4-PROGRAMS 2026-10-26 (session rem-a4, migrations/2026-10-26-rem-a4-programs.sql): the closing probe now reads 7 only when metric_history holds a daily read of 0 for each of the last 7 UTC days (the owner''s "0 for seven consecutive daily reads"); daily reads 70, 114, 173, 202, 203, 277, 122. Measured 20:10Z: 156 open issues are older than 24 h, 98 have no doer, 43 count as having one only through a code-task text line (20 of them have no live code task: every task failed or none was built), 15 hold a live work claim, 0 a live code task. The parts that move it: the breach doctor Phase B (a live doctor lease counts as a doer, issue 1000425), a doer for the 98, and v_issue_age_ladder counting a code-task line whose tasks all failed (a view change, filed as a finding here, not shipped). The issue stays open: an outcome.'
 WHERE id = 100299 AND status = 'open' AND instr(COALESCE(description, ''), 'REM-A4-PROGRAMS 2026-10-26') = 0;

UPDATE agent_issues SET updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000, description = COALESCE(description, '') || char(10) ||
  'REM-A4-PROGRAMS 2026-10-26 (session rem-a4, migrations/2026-10-26-rem-a4-programs.sql): the three families named in the title are no longer in the leak list; the leak moved. v_issue_family_throughput 20:10Z, families with net inflow above 0 and three or more open (opened/closed in 24 h, open): ROOT-CAUSE-1 10/0, 10 (doer: session rem-a2, claims on 1000301 to 1000310, migrations 2026-10-26-root-cause-probe-at-birth-2); BREACH-DOCTOR-1 7/0, 7 (doer: the code loop through each code-task line, PRs 4736, 4740 and 4746 landed three of them, 1000429 to 1000433 queued); METRIC-FIX-RELAPSED-1 8/2, 10 and METRIC-REGRESSION-1 13/8, 17 (doer: the breach doctor metric playbooks MD-1, MD-4 and MD-6 and session rem-a5, PR 4828; four 160-hour-old rows are outcome metrics that close when the metric converges); METRIC-UNMEASURED-1 7/2, 5 (doer: QUALITY-IMPROVEMENT-AUDIT-1 managers, hourly; rem-a2 METRIC-SAMPLE-GATE-1, PR 4829); LOOP-BREAKER-1 8/6, 4 (doer: none named for 1000321 and 1000375; 1000449 and 1000450 belong to TRIGGER-DEPTH-COMPILE-1, issue 1000447); FLEET-JOURNEY-FAILED-1 5/4, 5 (doer: session-old-issues-6d-2038, PR 4717). The closing probe now also requires issue_drain_ratio_24h at or above 1.5 (live 1.225), the second clause of the definition of done. The issue stays open: an outcome; no issue is closed to lower inflow.'
 WHERE id = 100294 AND status = 'open' AND instr(COALESCE(description, ''), 'REM-A4-PROGRAMS 2026-10-26') = 0;

UPDATE agent_issues SET updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000, description = COALESCE(description, '') || char(10) ||
  'REM-A4-PROGRAMS 2026-10-26 (session rem-a4, migrations/2026-10-26-rem-a4-programs.sql): the five parts, measured 20:10Z from code_tasks, v_sla_compliance and v_merge_reliability. The code-task-merge queue of 311.7 minutes is 252.3 minutes from task creation to the pull request opening and 59.4 minutes from open to merge (the lane merges 3 minutes after green; goal-level open-to-merge averages 74.6 minutes); 63 of 103 merged tasks of the last 7 days opened their PR inside the first hour and 40 waited longer, the worst being tasks that sat behind a held file or a red main (qnfo-fleet-control 18.6 h on average, scripts/attach-mind-q08-route.py 14.9 h, scripts/fleet-autoaudit.py 15.5 h, one task 72.6 h). Failures of the last 7 days: 35 failed and 4 NO-PROGRESS-CEILING-1 at 46 to 50 minutes against a 45-minute limit (ops_config path_hold_max_min, floor 30), 5 suite failures that pass on main, 3 SEARCH-text-not-found, 2 oversize-file-needs-anchor; the 200000-character patch class (b), the 3046 timeouts and the no-file-block class of the first measurement are gone (a: PR 3093 class handled by CONFLICT-REPAIR-DOER-1; e: the breach doctor and the RED-DRAIN dispatch give every issue a doer path). Merged share by task 103 of 222, by goal 0.758 (code_pr_merge_share_7d 0.762). The largest remaining gap is the wait before the pull request opens, which is the file-claim and red-main queue, not the merge lane: a change there is code in qnfo-code-orchestrator (claim hand-off) and not shipped by this note. The closing probe is unchanged (it measures queue minutes, merged share over two windows, closed against opened).'
 WHERE id = 100293 AND status = 'open' AND instr(COALESCE(description, ''), 'REM-A4-PROGRAMS 2026-10-26') = 0;

INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested)
SELECT 'session-rem-a4-programs',
  'an issue closes only on a probe that measures its own definition of done: a monitoring stub that is never probed, a refused backfill twin and an instant reading of a metric that needs seven daily reads each leave a program or lever issue with no honest path to closure',
  'REM-A4-PROGRAMS-1: contracts issue-100299, issue-100294, issue-100279, issue-100318 and issue-100366 rewritten to probes that measure the definition of done; the backfill twins of 100279, 100318 and 100366 superseded; dated notes on 100293, 100294 and 100299',
  'metric_history issues_over_24h_no_doer 70,114,173,202,203,277,122 (20-26 Oct); v_issue_family_throughput 20:10Z 7 families with net inflow; issue_drain_ratio_24h 1.225; v_sla_compliance code-task-merge 311.7 min (252.3 before the PR, 59.4 after); 36 verified loop merges, 1 CONTROL-PLANE-REVERTED-1 (1000171, session push); deployment_history 224 plain deploy rows and 0 staged rows for qnfo-ai and qnfo-gateway; metric_registry has no worker_requests_nonpublic_per_day',
  'applied by migration',
  'five remediation_contracts rows and three backfill twins; three dated issue notes; no worker, cap, threshold or metric formula changed',
  'the Rollback line restores the pre-change rows from bak_20261026_rem_a4_programs',
  'the program and lever issues have contracts that can fail for the right reason and pass only when the definition of done holds',
  '100299 cannot pass before seven daily zero reads (earliest 2026-11-02); 100279 cannot pass before 2026-10-27T04:00Z and then passes if no loop merge is reverted; 100318 and 100366 stay pending until a staged-rollout path and a request metric exist; 100294 and 100293 stay open until the metrics converge',
  '0', 'offline replay on node:sqlite of every new probe against fixtures that hold and that break each clause'
WHERE NOT EXISTS (SELECT 1 FROM decision_log d WHERE d.action LIKE 'REM-A4-PROGRAMS-1:%');
